      "rule_applied": "definition; Pay Wall / Free alternative",
      "rationale": "The review states that completing sticker progress is unavailable through ordinary play unless the player makes a substantial payment."
    },
    {
      "label": "P_CompleteTheCollection",
      "span": "on the stickers you will never get the last one or two",
      "rule_applied": "definition",
      "rationale": "The player describes pursuing the final missing stickers in order to complete a collection."
    }
  ],
